import{_ as a,C as o,o as r,c as h,aj as d,E as n}from"./framework.js";const m=JSON.parse('{"title":"控制台：数据中心 | Product / Console | Documentation","description":"控制台：数据中心 in Kooboo: 数据中心页是组织级管理入口。它不同于域名列表中的“更换某个域名的数据中心”；这里管理的是组织可用的数据中心列表和默认项。","frontmatter":{"title":"控制台：数据中心 | Product / Console | Documentation","description":"控制台：数据中心 in Kooboo: 数据中心页是组织级管理入口。它不同于域名列表中的“更换某个域名的数据中心”；这里管理的是组织可用的数据中心列表和默认项。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/console/data-centers.html"}]]},"headers":[],"relativePath":"zh/product/console/data-centers.md","filePath":"product/console/data-centers.md","lastUpdated":1780996899000}'),l={name:"zh/product/console/data-centers.md"};function c(s,t,i,b,p,u){const e=o("DocImage");return r(),h("div",null,[t[0]||(t[0]=d('<h1 id="控制台-数据中心" tabindex="-1">控制台：数据中心 <a class="header-anchor" href="#控制台-数据中心" aria-label="Permalink to &quot;控制台：数据中心&quot;">​</a></h1><blockquote><p>管理当前组织可用的数据中心，决定默认数据中心，并可跳转到目标数据中心后台。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>控制台</strong> -&gt; 左侧 <strong>数据中心</strong></td></tr><tr><td>深链</td><td><code>/_Admin/kconsole/serviceDataCenter</code></td></tr><tr><td>前端路由</td><td><code>/kconsole/serviceDataCenter</code></td></tr><tr><td>可见身份</td><td>组织管理员</td></tr></tbody></table><p>数据中心页是组织级管理入口。它不同于域名列表中的“更换某个域名的数据中心”；这里管理的是组织可用的数据中心列表和默认项。</p>',5)),n(e,{src:"/product/console/data-centers-overview.png",alt:"控制台数据中心列表",width:"1120"}),t[1]||(t[1]=d('<h2 id="页面结构" tabindex="-1">页面结构 <a class="header-anchor" href="#页面结构" aria-label="Permalink to &quot;页面结构&quot;">​</a></h2><p>数据中心页是单选表格。先选择一行，再使用表格上方操作按钮。</p><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td><code>Enable</code></td><td>对未启用的数据中心可用，确认后启用</td></tr><tr><td><code>Disable</code></td><td>对已启用的数据中心可用，确认后禁用</td></tr><tr><td><code>Set as Default</code></td><td>对已启用的数据中心可用，设置为默认数据中心</td></tr><tr><td>表格单选</td><td>默认数据中心不可选为待操作项</td></tr></tbody></table><p>表格列：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Name</td><td>数据中心名称</td></tr><tr><td>Description</td><td>数据中心说明</td></tr><tr><td>Enable Status</td><td>是否启用</td></tr><tr><td>Default</td><td>是否为默认数据中心</td></tr><tr><td>Go To</td><td>跳转到该数据中心后台</td></tr></tbody></table><h2 id="启用与禁用" tabindex="-1">启用与禁用 <a class="header-anchor" href="#启用与禁用" aria-label="Permalink to &quot;启用与禁用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>适合场景</th><th>注意</th></tr></thead><tbody><tr><td>启用</td><td>组织需要开始使用某个数据中心</td><td>启用前会弹确认</td></tr><tr><td>禁用</td><td>组织不再使用某个数据中心</td><td>禁用前会弹确认</td></tr><tr><td>设为默认</td><td>新站点或默认服务希望优先落到某个数据中心</td><td>只能对已启用的数据中心操作</td></tr></tbody></table><p>默认数据中心会影响后续部分组织级服务的默认落点。已有域名的数据中心调整，请在 <a href="./domains.html#续费-转移码与数据中心">域名</a> 页针对具体域名处理。</p><h2 id="跳转到数据中心" tabindex="-1">跳转到数据中心 <a class="header-anchor" href="#跳转到数据中心" aria-label="Permalink to &quot;跳转到数据中心&quot;">​</a></h2><p>表格最右侧的 <code>Go To</code> 图标用于打开目标数据中心后台。</p><table tabindex="0"><thead><tr><th>状态</th><th>行为</th></tr></thead><tbody><tr><td>已启用</td><td>使用当前登录 token 拼接 <code>auto_login=true</code>，在新标签页打开目标数据中心</td></tr><tr><td>未启用</td><td>图标不可用</td></tr></tbody></table><p>如果跳转后无法自动进入，通常先检查当前登录状态、组织权限，以及目标数据中心是否已启用。</p><h2 id="常见工作流" tabindex="-1">常见工作流 <a class="header-anchor" href="#常见工作流" aria-label="Permalink to &quot;常见工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>组织首次启用新数据中心</td><td>选择数据中心 -&gt; Enable -&gt; Set as Default</td></tr><tr><td>临时进入某个数据中心排查</td><td>确认已启用 -&gt; Go To</td></tr><tr><td>域名需要迁移数据中心</td><td>先确认组织数据中心可用 -&gt; 回 <a href="./domains.html">域名</a> 点击数据中心列调整</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../console.html">控制台概述</a></td><td>控制台菜单地图</td></tr><tr><td><a href="./domains.html">域名</a></td><td>单个域名的数据中心调整</td></tr><tr><td><a href="./organization.html">组织</a></td><td>当前组织与管理员身份</td></tr></tbody></table>',16))])}const f=a(l,[["render",c]]);export{m as __pageData,f as default};
